    /** `<head>` / `<tail>` pairs for the number-only shapes; the value between is copied. */
    private class Shape(val zhHead: String, val zhTail: String, val head: String, val tail: String)

    private val SHAPES: List<Shape> = listOf(
        Shape("随机等待 ", " 秒 · 可随时关闭", "隨機等候 ", " 秒 · 可隨時關閉"),
        Shape("放铳风险指数 ", "", "放銃風險指數 ", ""),
        Shape("和牌率 ", "%", "和牌率 ", "%"),
        Shape("进张 ", " 枚", "進張 ", " 枚"),
        Shape("拔北 ×", "：已计入三麻番数", "拔北 ×", "：已計入三麻番數"),
        Shape("", "向听 · 听牌后显示番点", "", "向聽 · 聽牌後顯示番點"),
        Shape("", " 人", "", " 人"),
        Shape("模型文件超过 ", " MiB 限制", "模型檔案超過 ", " MiB 限制"),
    )

    /** Traditional copy of one known source string, or [source] itself when unknown. */
    fun text(source: String): String =
        EXACT[source] ?: textTemplate(source) ?: textShape(source) ?: source

    /** True when this table can render [source] in Traditional Chinese. */
    fun knows(source: String): Boolean =
        EXACT.containsKey(source) || matchTemplate(source) != null || textShape(source) != null

    /**
     * Renders a templated message: the static wording is converted and every value the caller
     * interpolated is copied unchanged. `null` when the shape is unknown, so the caller keeps
     * the original text.
     */
    private fun textTemplate(source: String): String? {
        val hit = matchTemplate(source) ?: return null
        val row = hit.first
        val values = hit.second
        val out = StringBuilder(row.traditional.length + source.length)
        var at = 0
        for (part in row.traditional.split(VALUE)) {
            out.append(part)
            if (at < values.size) out.append(values[at++])
        }
        return out.toString()
    }

    /**
     * Matches [source] against [TEMPLATES]; the captured values run left to right. The rows
     * are tried in their Simplified form first, then in their converted form, so both a caller
     * that interpolates the raw Chinese text and one that interpolates into already-translated
     * wording are covered.
     */
    private fun matchTemplate(source: String): Pair<Template, List<String>>? {
        // the Simplified form the app wrote
        for (row in TEMPLATES) {
            val values = matchOneForm(row.source, source) ?: continue
            return row to values
        }
        // the same row with its static wording already converted (a caller that translated
        // the shell first and interpolated after it); a 0- or 1-value row is checked as a
        // whole here, because its text is the right side of an EXACT row and the extra
        // character fixes would otherwise be lost
        for (row in TEMPLATES) {
            if (row.traditional == row.source) continue
            val count = row.source.count { it == VALUE }
            val values = if (count <= 1) {
                if (matchOneForm(row.traditional, source) == null) continue
                listOf()
            } else {
                matchOneForm(row.traditional, source) ?: continue
            }
            return row to values
        }
        return null
    }

    /**
     * Anchored match of one template form: the first literal starts the message, the last one
     * ends it, a value is whatever sits between two literals, and the tail value must start
     * after the last literal. A message with extra text around the known wording is not a hit.
     */
    private fun matchOneForm(template: String, source: String): List<String>? {
        val parts = template.split(VALUE)
        if (!source.startsWith(parts.first()) || !source.endsWith(parts.last())) return null
        val values = ArrayList<String>(parts.size - 1)
        var at = parts.first().length
        for (k in 1 until parts.size - 1) {
            val part = parts[k]
            val found = source.indexOf(part, at)
            if (found < 0) return null
            values.add(source.substring(at, found))
            at = found + part.length
        }
        val tailStart = source.length - parts.last().length
        if (tailStart < at) return null
        values.add(source.substring(at, tailStart))
        return values
    }

    /**
     * Renders the known `<head><value><tail>` shapes of [SHAPES]; `null` when the source is
     * none of them, so the caller keeps the original text untouched. The value between head
     * and tail is copied without any conversion.
     */
    private fun textShape(source: String): String? {
        for (shape in SHAPES) {
            if (!source.startsWith(shape.zhHead) || !source.endsWith(shape.zhTail)) continue
            if (source.length < shape.zhHead.length + shape.zhTail.length) continue
            val middle = source.substring(shape.zhHead.length, source.length - shape.zhTail.length)
            return shape.head + middle + shape.tail
        }
        return null
    }
}
